import { db } from '../firebase/config';
import { collection, setDoc, getDoc, getDocs, updateDoc, deleteDoc, doc, query, where, serverTimestamp } from 'firebase/firestore';
import type { Support_Request } from '../types/Support_Request';

// Collection: supportRequests. Document IDs are generated by Firestore and copied into reqID.
const COLLECTION = 'supportRequests';

// Newest first. Sorted here rather than with orderBy, which would need a composite index for every filter.
const newestFirst = (a: Support_Request, b: Support_Request) =>
  (b.reqTimestamp?.toMillis() ?? 0) - (a.reqTimestamp?.toMillis() ?? 0);

// ~~~~~~~~~~ CREATE ~~~~~~~~~~

// Returns the new reqID. The status and timestamp are set by the caller / server, not trusted from the form.
export const createSupportRequest = async (
  data: Omit<Support_Request, 'reqID' | 'reqTimestamp'>
): Promise<string> => {
  try {
    const ref = doc(collection(db, COLLECTION));
    await setDoc(ref, { ...data, reqID: ref.id, reqTimestamp: serverTimestamp() });
    return ref.id;
  } catch (error) {
    console.error('Error creating support request:', error);
    throw error;
  }
};

// ~~~~~~~~~~ READ ~~~~~~~~~~

// Get a request by reqID
export const getSupportRequest = async (reqID: string): Promise<Support_Request | null> => {
  try {
    const snap = await getDoc(doc(db, COLLECTION, reqID));
    return snap.exists() ? (snap.data() as Support_Request) : null;
  } catch (error) {
    console.error(`Error getting support request "${reqID}":`, error);
    throw error;
  }
};

// Get all requests made by a student (My Requests)
export const getRequestsByStudent = async (studUID: string): Promise<Support_Request[]> => {
  try {
    const snap = await getDocs(query(collection(db, COLLECTION), where('studUID', '==', studUID)));
    return snap.docs.map(d => d.data() as Support_Request).sort(newestFirst);
  } catch (error) {
    console.error(`Error getting requests for student "${studUID}":`, error);
    throw error;
  }
};

// Get all requests sent to a volunteer (Incoming Requests)
export const getRequestsByVolunteer = async (volUID: string): Promise<Support_Request[]> => {
  try {
    const snap = await getDocs(query(collection(db, COLLECTION), where('volUID', '==', volUID)));
    return snap.docs.map(d => d.data() as Support_Request).sort(newestFirst);
  } catch (error) {
    console.error(`Error getting requests for volunteer "${volUID}":`, error);
    throw error;
  }
};

// Get a student's requests with a given status
export const getRequestsByStudentAndStatus = async (
  studUID: string,
  reqStatus: Support_Request['reqStatus']
): Promise<Support_Request[]> => {
  try {
    const snap = await getDocs(
      query(collection(db, COLLECTION), where('studUID', '==', studUID), where('reqStatus', '==', reqStatus))
    );
    return snap.docs.map(d => d.data() as Support_Request).sort(newestFirst);
  } catch (error) {
    console.error(`Error getting "${reqStatus}" requests for student "${studUID}":`, error);
    throw error;
  }
};

